  }
}

const xs = Array.from({ length: 32 }, () => Float64Array.from({ length: 8 }, gauss));
const ys = Array.from({ length: 32 }, () => Math.floor(rnd() * 5));
const net = new Net([8, 16, 5]);

const flatGrad = (): number[] => net.layers.flatMap((L) => [...L.gW, ...L.gb]);

// 1) 큰 묶음(32개)의 기울기
const loss = net.backward(xs, ys); // 기울기 계산
const bigGrad = flatGrad();

// 2) 기울기 누적: 작은 묶음(8개) 4번의 기울기를 평균(÷ 4)해서 쌓으면 큰 묶음 1번과 같다
const acc = new Array(bigGrad.length).fill(0);
for (let i = 0; i < 4; i++) {
  net.backward(xs.slice(i * 8, (i + 1) * 8), ys.slice(i * 8, (i + 1) * 8));
  flatGrad().forEach((g, k) => { acc[k] += g / 4; }); // 나누기 4: 평균을 맞추기 위해
}
const same = acc.every((g, k) => Math.abs(g - bigGrad[k]) < 1e-9);
console.log("누적 기울기 = 큰 묶음 기울기?", same);

// 3) 한 step: 기울기 자르기 → 옵티마이저 한 걸음
net.backward(xs, ys);
const norm = Math.sqrt(flatGrad().reduce((s, g) => s + g * g, 0));
const scale = Math.min(1, 1.0 / (norm + 1e-6)); // 기울기 전체 길이가 1을 넘으면 길이 1로 줄임
for (const L of net.layers) { L.gW.forEach((g, i) => { L.gW[i] = g * scale; }); L.gb.forEach((g, i) => { L.gb[i] = g * scale; }); }
const w0 = net.layers[0].W[0];
net.adam(1e-2); // 가중치 갱신
const lossAfter = net.loss(xs, ys);
console.log(`loss ${loss.toFixed(4)} → ${lossAfter.toFixed(4)} · 기울기 크기 ${norm.toFixed(3)} (자른 뒤 ≤ 1) · 첫 가중치 변화 ${Math.abs(net.layers[0].W[0] - w0).toFixed(4)}`);
check(lossAfter < loss && norm > 0 && same && net.layers[0].W[0] !== w0, "한 step 뒤 loss가 줄고, 누적 기울기가 큰 묶음 기울기와 같아야 해요.");

