// D12 · Part 4 · CER 계산 (compute_metrics) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d12_metrics.ts   (글자 번호 배열로 만든 모의 예측 · 인터넷·GPU 불필요)
//   -100을 패딩 번호로 되돌려 글자로 바꾸고, 문장 부호·띄어쓰기를 지운 뒤 CER을 계산한다 (편집 거리 직접 계산)
//   흉내 낸 부분: Whisper 토크나이저 대신 글자 목록(VOCAB)으로 번호 ↔ 글자 변환
const PAD_ID = 0;
const VOCAB = ["<pad>", ...[..."오늘날씨가좋네요회의를시작합니다 .,!"]];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const decode = (ids: number[]): string => ids.filter((i) => i !== PAD_ID).map((i) => VOCAB[i]).join("");
const encode = (s: string): number[] => [...s].map((c) => VOCAB.indexOf(c));

function normalize(s: string): string {
  // D10 정규화의 간단판: 문장 부호 · 띄어쓰기 차이 무시
  return s.toLowerCase().replace(/[^\p{L}\p{N}_\s]/gu, "").replace(/\s+/g, "");
}

function editDistance(a: string, b: string): number {
  const d = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return d[b.length];
}

function computeMetrics(predIds: number[][], labelIds: number[][]): { cer: number } {
  const labels = labelIds.map((r) => r.map((v) => (v === -100 ? PAD_ID : v))); // 빈칸 -100 은 글자로 못 바꾸니 패딩 번호로
  const pred = predIds.map((r) => normalize(decode(r)) || "∅"); // 빈 예측 대비
  const ref = labels.map((r) => normalize(decode(r)));
  const errors = ref.reduce((s, r, i) => s + editDistance(r, pred[i]), 0);
  return { cer: (100 * errors) / ref.reduce((s, r) => s + r.length, 0) };
}

const pad = (rows: number[][], n: number, fill: number): number[][] => rows.map((r) => [...r, ...Array(n - r.length).fill(fill)]);

const refs = ["오늘 날씨가 좋네요.", "회의를 시작합니다!"];
const labels = pad(refs.map(encode), 12, -100);
const same = pad(refs.map(encode), 12, PAD_ID);
const oneOff = pad([encode("오늘 날씨가 좋네오."), encode(refs[1])], 12, PAD_ID); // 한 글자만 다름
console.log("정답 = 예측:", computeMetrics(same, labels));
console.log("한 글자 틀림:", computeMetrics(oneOff, labels));
const chars = refs.map(normalize).join("").length;
check(computeMetrics(same, labels).cer === 0 && Math.abs(computeMetrics(oneOff, labels).cer - 100 / chars) < 1e-9,
  "정답 그대로면 CER 0, 한 글자 틀리면 1 ÷ 전체 글자 수 × 100 이어야 해요.");

