// D12 · Part 6 · 학습 곡선 읽기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d12_curves.ts   (몇 초 · GPU·인터넷 불필요)
//   장난감 분류 모델을 세 가지 조건으로 학습해 train · valid loss 곡선을 모으고, 곡선 모양으로 '안 배움 · 잘 배움 · 외움(과적합)'을 판정한다
//   흉내 낸 부분: Whisper 대신 작은 MLP, 소리 대신 잡음이 많은 합성 특징(학습 문제 20개 vs 검증 300개)
const K = 5, DIM = 20;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗을 주면 늘 같은 순서의 난수를 주는 작은 생성기
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
let rnd = mulberry32(0);
const gauss = (): number => Math.sqrt(-2 * Math.log(Math.max(rnd(), 1e-12))) * Math.cos(2 * Math.PI * rnd());

type Layer = { W: Float64Array; b: Float64Array; nin: number; nout: number; gW: Float64Array; gb: Float64Array; m: Float64Array; v: Float64Array; mb: Float64Array; vb: Float64Array };

class Net {
  layers: Layer[] = [];
  t = 0;
  constructor(sizes: number[]) {
    const z = (n: number): Float64Array => new Float64Array(n);
    for (let i = 0; i < sizes.length - 1; i++) {
      const [nin, nout] = [sizes[i], sizes[i + 1]];
      this.layers.push({ W: Float64Array.from({ length: nin * nout }, () => gauss() / Math.sqrt(nin)), b: z(nout), nin, nout, gW: z(nin * nout), gb: z(nout), m: z(nin * nout), v: z(nin * nout), mb: z(nout), vb: z(nout) });
    }
  }
  forward(x: Float64Array): Float64Array[] {
    const acts = [x];
    this.layers.forEach((L, l) => {
      const out = new Float64Array(L.nout);
      for (let o = 0; o < L.nout; o++) {
        let s = L.b[o];
        for (let i = 0; i < L.nin; i++) s += L.W[o * L.nin + i] * acts[l][i];
        out[o] = l < this.layers.length - 1 ? Math.tanh(s) : s;
      }
      acts.push(out);
    });
    return acts;
  }
  probs(x: Float64Array): Float64Array {
    const z = this.forward(x).at(-1) as Float64Array;
    const mx = Math.max(...z);
    const e = z.map((v) => Math.exp(v - mx));
    const s = e.reduce((a, c) => a + c, 0);
    return e.map((v) => v / s);
  }
  loss(xs: Float64Array[], ys: number[]): number {
    return xs.reduce((s, x, n) => s - Math.log(Math.max(this.probs(x)[ys[n]], 1e-12)), 0) / xs.length;
  }
  // 묶음 전체의 평균 loss를 계산하고, 기울기를 layers[].gW · gb 에 쌓는다
  backward(xs: Float64Array[], ys: number[]): number {
    for (const L of this.layers) { L.gW.fill(0); L.gb.fill(0); }
    xs.forEach((x, n) => {
      const acts = this.forward(x);
      let delta = this.probs(x).map((v, k) => (v - (k === ys[n] ? 1 : 0)) / xs.length);
      for (let l = this.layers.length - 1; l >= 0; l--) {
        const L = this.layers[l];
        const prev = new Float64Array(L.nin);
        for (let o = 0; o < L.nout; o++) {
          L.gb[o] += delta[o];
          for (let i = 0; i < L.nin; i++) { L.gW[o * L.nin + i] += delta[o] * acts[l][i]; prev[i] += L.W[o * L.nin + i] * delta[o]; }
        }
        delta = l > 0 ? prev.map((v, i) => v * (1 - acts[l][i] ** 2)) : prev;
      }
    });
    return this.loss(xs, ys);
  }
  adam(lr: number): void {
    this.t++;
    const upd = (w: Float64Array, g: Float64Array, m: Float64Array, v: Float64Array): void => {
      for (let i = 0; i < w.length; i++) {
        m[i] = 0.9 * m[i] + 0.1 * g[i];
        v[i] = 0.999 * v[i] + 0.001 * g[i] * g[i];
        w[i] -= (lr * (m[i] / (1 - 0.9 ** this.t))) / (Math.sqrt(v[i] / (1 - 0.999 ** this.t)) + 1e-8);
      }
    };
    for (const L of this.layers) { upd(L.W, L.gW, L.m, L.v); upd(L.b, L.gb, L.mb, L.vb); }
  }
}

const PROTO = Array.from({ length: K }, () => Float64Array.from({ length: DIM }, gauss));

function data(n: number): { xs: Float64Array[]; ys: number[] } {
  const ys = Array.from({ length: n }, () => Math.floor(rnd() * K));
  return { xs: ys.map((y) => Float64Array.from({ length: DIM }, (_, d) => PROTO[y][d] + 2.5 * gauss())), ys };
}
const train = data(20), valid = data(300);

function run(lr: number, width: number, steps: number): [number[], number[]] {
  rnd = mulberry32(1); // 같은 출발점에서 시작
  const net = new Net([DIM, width, K]);
  const tr: number[] = [], va: number[] = [];
  for (let s = 0; s < steps; s++) {
    tr.push(net.backward(train.xs, train.ys));
    net.adam(lr);
    va.push(net.loss(valid.xs, valid.ys));
  }
  return [tr, va];
}

function diagnose(tr: number[], va: number[]): string {
  // 곡선 읽는 규칙: train이 거의 안 줄면 안 배움, valid가 바닥을 찍고 다시 오르면 외움, 둘 다 줄면 잘 배움
  if (tr.at(-1)! > 0.9 * tr[0]) return "안 배움";
  if (va.at(-1)! > Math.min(...va) * 1.15 && tr.at(-1)! < 0.5 * va.at(-1)!) return "외움";
  return "잘 배움";
}

const runs: [string, [number[], number[]]][] = [["학습률 너무 작음", run(1e-5, 64, 200)], ["적당히 학습", run(3e-3, 4, 60)], ["너무 오래 학습", run(1e-2, 256, 400)]];
const verdict: string[] = [];
for (const [name, [tr, va]] of runs) {
  const d = diagnose(tr, va);
  verdict.push(d);
  const lo = Math.min(...va);
  console.log(`${name.padEnd(12)} train ${tr[0].toFixed(2)}→${tr.at(-1)!.toFixed(2)} · valid 최저 ${lo.toFixed(2)}(step ${va.indexOf(lo)}) → 끝 ${va.at(-1)!.toFixed(2)} · 판정: ${d}`);
}
check(verdict.join() === "안 배움,잘 배움,외움", "곡선 모양대로 안 배움 · 잘 배움 · 외움이 나와야 해요.");
